//! Native pattern validity connects actual edits, reporting, submission and paint.
use super::*;
struct Fixture(std::path::PathBuf);impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{(0..app.document.nodes.len()).find(|&n|app.document.attr(n,"id")==Some(id)).unwrap()}
fn click(app:&mut App,n:usize){let r=app.page.controls.iter().find(|r|r.node==n).unwrap();let(x,y)=(r.x+r.width/2,app.content_top()+r.y+r.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);}
#[test]
fn native_text_type_transition_actual_app_edits_reporting_submit_recovery_paint_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-text-type-transition-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>input,button{display:block}#paint{position:absolute;left:420px;top:160px;width:40px;height:30px;background:#114455}#paint.done{background:#cc2244}#stable{position:absolute;left:420px;top:100px}</style><form id=form><input id=field type=text name=q pattern='(?i:😀ab)'><button id=send name=send>Submit</button></form><button id=go name=go type=button>Validate</button><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><div id=paint></div><div id=destination></div><script>var field=document.getElementById('field'),form=document.getElementById('form'),view=field.validity,round=0,inputs=0,invalid=0;field.addEventListener('input',function(e){if(!e.isTrusted)throw 'trusted edit';inputs++;if(view.patternMismatch!==(field.value!=='😀AB')||view.tooLong)throw 'flags before input listener';});field.addEventListener('invalid',function(e){if(!e.isTrusted||!view.patternMismatch||view.valid)throw 'trusted pattern invalid';invalid++;});form.addEventListener('submit',function(e){if(!e.isTrusted||e.submitter!==document.getElementById('send')||!view.valid||invalid!==2)throw 'trusted valid submission';e.preventDefault();document.title='Submitted';});document.getElementById('go').onclick=function(){if(field.validity!==view)throw 'stable view';if(round===0){field.type='password';if(field.type!=='password')throw 'password state';if(view.patternMismatch||view.tooLong||!view.valid||!field.reportValidity())throw 'empty optional';document.title='Empty';field.focus();}else if(round===1){field.type='search';if(field.type!=='search')throw 'search state';if(!view.patternMismatch||view.valid||field.validationMessage!=='Match the required pattern: q.'||field.reportValidity()!==false)throw 'native user mismatch';document.title='Mismatch';}else if(round===2){field.type='tel';if(field.type!=='tel')throw 'tel state';if(view.patternMismatch||!view.valid||!field.reportValidity()||inputs!==3)throw 'native repaired';document.getElementById('paint').className='done';document.title='Valid';}else{field.type='password';if(field.type!=='password')throw 'masked repaired state';field.pattern='(?i:x)';field.value='X';if(view.patternMismatch||view.tooLong||!view.valid||!field.reportValidity())throw 'script pattern recovery';document.title='Script';}round++;};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);
 let field=node(&app,"field");let go=node(&app,"go");let send=node(&app,"send");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let r=app.page.controls.iter().find(|r|r.node==field).unwrap();let rect=(r.x,r.y,r.width,r.height);app.forms.script_set_value(neighbor,"neighbor edit").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}
 let before=app.draw();click(&mut app,go);assert_eq!(app.document.title,"Empty");assert!(app.forms.controls[&field].password);assert!(matches!(app.focus,Focus::Control(n)if n==field));app.text_input('😀');click(&mut app,go);assert_eq!(app.document.title,"Mismatch");assert!(!app.forms.controls[&field].password);assert!(app.failed);assert_eq!(app.status,"Match the required pattern: q.");click(&mut app,send);assert_eq!(app.document.title,"Mismatch");assert!(!app.forms.controls[&field].password);assert!(app.failed);assert_eq!(app.status,"Match the required pattern: q.");assert!(matches!(app.focus,Focus::Control(n)if n==field));app.text_input('A');app.text_input('B');click(&mut app,go);assert_eq!(app.document.title,"Valid");assert!(!app.failed&&app.status.is_empty());click(&mut app,send);assert_eq!(app.document.title,"Submitted");assert!(!app.failed&&!app.is_loading());click(&mut app,go);assert_eq!(app.document.title,"Script");assert!(app.forms.controls[&field].password);assert!(!app.failed&&app.status.is_empty());assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());let painted=app.draw();let pixel=(app.content_top()+170)as usize*painted.width+430;assert_eq!(painted.pixels[pixel],0xcc2244);assert_ne!(before.pixels[pixel],painted.pixels[pixel]);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("neighbor edit".into(),5,2,1));let r=app.page.controls.iter().find(|r|r.node==field).unwrap();assert_eq!((r.x,r.y,r.width,r.height),rect);assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!((app.raw.clone(),app.location.clone(),app.script_epoch),(raw,location,epoch));
}

#[test]
fn native_text_type_transition_invalidates_captured_native_editor_request(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-type-continuation-{}.html",std::process::id())));
 std::fs::write(&file.0,"<!doctype html><input id=field value=AB>").unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed);
 let field=node(&app,"field");app.focus_control(field);
 let request=app.platform_request(PlatformAction::Paste);
 // Change only the native type through the actual page bridge: no App input
 // invalidation, navigation, editor/value/focus or neighboring state change.
 assert_eq!(app.scripting.as_mut().unwrap().console_eval(&mut app.document,&mut app.forms,"document.getElementById('field').type='password';").errors,0);
 assert!(app.forms.controls[&field].password);assert!(!app.complete_platform_request(request,PlatformCompletion::Paste("stale".into())));assert_eq!(app.forms.controls[&field].value.text(),"AB");
 let request=app.platform_request(PlatformAction::Paste);assert!(app.complete_platform_request(request,PlatformCompletion::Paste("C".into())));assert_eq!(app.forms.controls[&field].value.text(),"ABC");
 app.key(0x41,true,false,false);assert!(matches!(app.key(0x43,true,false,false),PlatformAction::None));assert!(matches!(app.key(0x58,true,false,false),PlatformAction::None));
}
